declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/layout.php';require_once __DIR__.'/../app/business_microsite_v1130.php';require_once __DIR__.'/../app/business_crm_ui_v1180.php';$u=current_user();if(!$u||!(has_permission('businesses.manage',$u)||has_permission('settings.manage',$u))){http_response_code(403);exit('Forbidden');}$uid=(int)$u['id'];$rows=sk1130_businesses('',200);$bid=(int)($_REQUEST['business_id']??0);if($bid<1&&$rows)$bid=(int)$rows[0]['id'];$b=$bid?sk1130_business($bid):[];$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&$b){csrf_check();$a=(string)($_POST['action']??'');if($a==='reply'){sk1180_message_add((int)$_POST['conversation_id'],'admin',(string)$_POST['message'],$uid);$msg='Reply sent.';}elseif($a==='quote'){sk1180_quote_create($bid,(int)$_POST['contact_id'],(int)($_POST['conversation_id']??0),$_POST,$uid);$msg='Quotation sent.';}elseif($a==='followup'){sk1180_followup_create($bid,(int)$_POST['contact_id'],(string)$_POST['due_at'],(string)$_POST['note'],$uid);$msg='Follow-up added.';}elseif($a==='followup_done'){sk1180_followup_done((int)$_POST['followup_id'],$bid);$msg='Follow-up completed.';}}}catch(Throwable $e){$err=$e->getMessage();}page_start('Business Customer CRM',true);?><link rel="stylesheet" href="/assets/business-crm-v1180.css?v=1180"><div class="crm1180"><form class="chooser"><label>Business<select name="business_id" onchange="this.form.submit()"><?php foreach($rows as $x):?><option value="<?=(int)$x['id']?>" <?=(int)$x['id']===$bid?'selected':''?>><?=sk1130_h((string)sk1130_business_value($x,['name'],'Business'))?></option><?php endforeach;?></select></label></form><?php if($msg):?><div class="notice ok"><?=sk1130_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1130_h($err)?></div><?php endif;?><?php if($b)sk1180_render_crm_page($b,$u,true);?></div><?php require __DIR__.'/../app/end.php';?>